        hom: mobHom([C(0, 0), C(1, 0), C(1, 0), C(0, 0)]),
        homTex: (v) => mobHomTex([C(0, 0), C(1, 0), C(1, 0), C(0, 0)], v),
        tex: (a) => ({ s: `\\frac{1}{${a.s}}`, p: 4 }),
