      if (r.inverse) r.inverse = { type: 'blaschke', params: { a: fmtC(CX.neg(CX.mul(e, a))), phi: phi === 0 ? 0 : -phi } };
      else if (ra === 1) r.inverseNote = $t('|a| = 1 makes this map constant, so it has no inverse');
