      const th = dhAngle(s.theta);
      if (th == null) return null;
      return {
        key: JSON.stringify(['ray', th, ck]), kindKey: JSON.stringify(['ray', th, s.id]),
        gen: () => CX.dhRayGen(th, { c, R0: CX.DH_R, S: DH_S, levels: DH_LEVELS }),
