      key: JSON.stringify(['eq', r, ck]), kindKey: JSON.stringify(['eq', r, s.id]),
      gen: () => CX.dhEquipotentialGen(Math.log(r), { c, tol: 0.01 * r, R0: CX.DH_R }),
