  // every n-th point of a traced curve (the ends kept), with its angles and potentials, for dhFollow
  function dhEvery(curve, max) {
    const P = curve.pts || curve, n = P.length, k = Math.max(1, Math.ceil(n / max));
    if (k === 1) return curve;
