    if (have && have.full) return have.curve;
    if (!Region.dhAsync) {
      const g = job.gen();
      let r;
      while (!(r = g.next()).done) { /* trace */ }
      dhMemoSet(job.key, { curve: r.value, full: true });
      DH_LAST.set(job.kindKey, r.value);
      return r.value;
    }
    if (!have) {
      const last = DH_LAST.get(job.kindKey);
