  const old = { shapes: [{ id: 's1', kind: 'disc', c: [0, 0], r: 1 }], steps: [{ type: 'exp', params: {}, on: true }], rightMode: 'image', v4: true };
  eq(await P.decodeLink('0.' + Buffer.from(JSON.stringify({ v: 1, s: old })).toString('base64url')), old, 'older state in a link');
  for (const [bad, re] of [['', /does not hold/], ['1.%%%', /does not hold/], ['1.AAAA', /damaged/], ['9.AAAA', /newer version/], ['0.' + Buffer.from('{"v":1}').toString('base64url'), /does not hold/], ['0.' + Buffer.from('not json').toString('base64url'), /damaged/]]) {
    let msg = '';
    try { await P.decodeLink(bad); } catch (e) { msg = e.message; }
    ok(re.test(msg), `bad link ${bad.slice(0, 12)}: ${msg}`);
  }
  const sc = P.scene(state);
  eq(P.readScene(sc), state, 'scene round trip');
  eq(P.readScene(JSON.stringify(state)), state, 'a bare saved state opens as a scene');
  for (const [bad, re] of [['{', /not JSON/], ['[1]', /not a scene/], ['{"app":"other","kind":"scene","state":{}}', /not a scene/]]) {
    let msg = '';
    try { P.readScene(bad); } catch (e) { msg = e.message; }
    ok(re.test(msg), `bad scene ${bad}: ${msg}`);
  }
  // an example's number keeps the user's number it stands in for (ex.was), in the saved state
  const sx = P.sanitize([{ name: 'N', value: 8, min: 1, max: 30, step: 1, ex: { was: { name: 'N', value: 3, min: 1, max: 9, step: 1, ex: true } } }, { name: 'M', value: 2, ex: true }, { name: 'K', value: 1, ex: { was: 7 } }]);
  eq(sx[0].ex, { was: { name: 'N', value: 3, min: 1, max: 9, step: 1 } }, 'sanitize keeps ex.was, as a plain number');
  eq(sx[1].ex, true, 'ex: true stays');
  eq(sx[2].ex, true, 'a damaged ex.was is dropped, ex stays');
  eq(P.sanitize(JSON.parse(JSON.stringify(sx))), sx, 'sanitize with ex.was is idempotent');
  // (h) complex numbers: a = 1 + i, formulas, real-only fields, resolve and save round trips
  list.length = 0;
  ok(P.add('a', { value: 1 }) && P.get('a') === 1 && !P.isComplex('a'), 'a real number stays real');
  eq(P.set('a', '1 + i'), '', 'a free number can be typed as a complex number');
  eq(P.getC('a'), { re: 1, im: 1 }, 'getC reads {re, im}');
  eq(P.get('a'), 1, 'get keeps the real part');
  ok(P.isComplex('a') && P.list()[0].im === 1, 'the entry holds im');
  eq(val('a'), [1, 1], 'a formula reads a as 1 + i');
  eq(val('a^2'), [0, 2], 'a² = 2i');
  eq(val('Re a'), [1, 0], 'Re a'); eq(val('Im a'), [1, 0], 'Im a');
  ok(Math.abs(val('|a|')[0] - Math.SQRT2) < 1e-12, '|a|');
  ok(Math.abs(val('arg a')[0] - Math.PI / 4) < 1e-12, 'arg a');
  eq(val('conj a'), [1, -1], 'conj a');
  eq(val('\\bar{a}'), [1, -1], '\\bar{a}');
  eq(val('\\overline{a}'), [1, -1], '\\overline{a}');
  eq(P.add('b', { value: 2 }) && P.set('b', 'a^2'), '', 'a number by formula may be complex');
  eq(P.getC('b'), { re: 0, im: 2 }, 'b = a² = 2i');
  P.set('a', '1 - i');
  eq(P.getC('b'), { re: 0, im: -2 }, 'b follows a');
  let e = ''; try { P.evalReal('a'); } catch (x) { e = x.message; }
  ok(/a is complex: use Re a, Im a or \|a\|/.test(e), 'a real-only field names the number: ' + e);
  e = ''; try { P.evalReal('i'); } catch (x) { e = x.message; }
  ok(/must be real/.test(e), 'a complex constant without a name keeps the old message');
  eq(P.evalReal('Re a + Im a'), 0, 'real-only fields read Re a and Im a');
  eq(P.evalVal('a + 1'), { re: 2, im: -1 }, 'evalVal');
  eq(P.set('a', 0.5), '', 'a real value clears the imaginary part');
  ok(!('im' in P.list()[0]) && !P.isComplex('a'), 'back to real: no im saved');
  P.set('a', { re: -0.5, im: 0.3 });
  for (const [re, im, txt] of [[0.5, 0.3, '0.5+0.3'], [-0.5, -0.3, '-0.5-0.3'], [0, 0.3, '0.3'], [0, 1, ''], [0, -1, '-'], [2, 1, '2+'], [1e-7, -2e-9, '1e-7-2e-9'], [-0, 0.5, '0.5']]) {
    P.set('a', { re, im });
    const r = P.resolve('a');
    ok(r === `(${txt}i)`, `resolve ${re},${im}: ${r}`);
    const v = Expr.constValue(r);
    ok(v.re === re && v.im === im, `resolve round trip ${re},${im}: ${v.re},${v.im}`);
  }
  P.set('a', 0.5);
  eq(P.resolve('2a'), '2(0.5)', 'a real number resolves as before');
  eq(P.resolve('a', { a: { re: 1, im: -1 } }), '(1-i)', 'resolve with a value override');
  P.set('a', { re: 1, im: 2 });
  const san2 = P.sanitize(JSON.parse(JSON.stringify(P.list())));
  eq(san2.find((q) => q.name === 'a').im, 2, 'sanitize keeps im');
  eq(P.sanitize([{ name: 'k', value: 1, im: 'x' }, { name: 'm', value: 1, im: 0 }]).map((q) => 'im' in q), [false, false], 'sanitize drops a bad or zero im');
  eq(P.sanitize(san2), san2, 'sanitize with im is idempotent');
  const cstate = { shapes: [], steps: [{ type: 'custom', params: { expr: 'a z' }, on: true }], params: san2 };
  eq(await P.decodeLink(await P.encodeLink(cstate)), cstate, 'a link with a complex number round-trips');
  eq(P.readScene(P.scene(cstate)), cstate, 'a scene with a complex number round-trips');
  // an older build reads the real part only: value is still the real part, nothing else is required of it
  eq(san2.find((q) => q.name === 'a').value, 1, 'the real part is the saved value');
  // inline: deleting a complex number writes its value into the formulas
  P.inline('a');
  eq(P.list().find((q) => q.name === 'b').expr, '(1+2i)^2', 'inline writes the complex value');
  ok(P.tex('a') !== undefined, 'tex of a name');
  // comparisons name a complex shared number instead of reading its real part (Re z < a, a = 0.5 + 0.3i)
  list.length = 0;
  P.add('a', { value: { re: 0.5, im: 0.3 } });
  const rel = (src) => Expr.classifyRelation(Expr.parse(src, { allowRel: true }));
  for (const src of ['Re z < a', 'a z < 1', 'Re z < 2a', 'Im z >= conj a']) {
    const r = rel(src);
    ok(r.dim === 'error' && /a is complex: use Re a, Im a or \|a\|/.test(r.error), `comparison ${src}: ${JSON.stringify(r)}`);
    let m = ''; try { Expr.compileLevel(Expr.parse(src, { allowRel: true })); } catch (e) { m = e.message; }
    ok(/a is complex/.test(m), `compileLevel ${src}: ${m}`);
  }
  for (const src of ['Re z < Re a', '|z - a| < 2', 'Re(z a) < 1', 'Im z < arg a', 'Re z < i', 'Re z < |a|']) ok(rel(src).dim === 'area', `comparison ${src} stays an area: ${JSON.stringify(rel(src))}`);
  ok(rel('Re z = a').dim === 'error', 'an equation with a complex number keeps its own message');
  P.set('a', 0.5);
  ok(rel('Re z < a').dim === 'area', 'the same comparison reads once a is real');
  // a number that is playing and becomes complex stops (and one that becomes real again)
  global.requestAnimationFrame = () => 0;
  P.add('q', { value: 1 });
  P.togglePlay('q');
  ok(P.isPlaying('q'), 'q plays');
  P.set('q', '1 + i');
  ok(!P.isPlaying('q'), 'editing a playing number into a complex value stops its play');
  P.set('q', 2);
  ok(!P.isPlaying('q'), 'and a real value does not restart it');
  console.log(`${n - fails}/${n} passed`);
  if (fails) process.exit(1);
})().catch((e) => { console.error(e); process.exit(1); });

// A point's exact preimages through a chain (#291, #252 option 3): Inverse.pointPre composes the ops' exact branches
// when every op has finitely many. Each listed z maps to p to 1e-9, the count is the product of the branch counts (the
// distinct roots of a generic p), non-rational steps and chains above the cap are not exact (the app searches there).
// Run: node test/t_point_pre.js   (exit code 1 on any failure)
global.CX = require('../src/cx.js');
global.Expr = require('../src/parse.js');
global.Funcs = require('../src/funcs.js');
const Inverse = require('../src/inverse.js');
const C = CX.C;
let bad = 0, n = 0;
const check = (name, ok, info = '') => { n++; if (!ok) { bad++; console.log('FAIL', name, info); } };
const step = (type, params = {}) => ({ type, params: Object.assign(Funcs.defaults(type), params), on: true });
const chain = (steps) => ({ steps, built: steps.map((st) => Funcs.build(st)) });
const F = (ch, a, b) => (z) => { for (let k = a; k < b; k++) z = ch.built[k].f(z); return z; };
// every listed z maps to p, the list has `want` distinct points
function exact(name, steps, p, want, a = 0, b = steps.length) {
  const ch = chain(steps), plan = Inverse.planChain(ch.steps, ch.built, a, b), r = Inverse.pointPre(plan, p);
  check(`${name}: exact`, r.exact, r.reason);
  if (!r.exact) return r;
  const f = F(ch, a, b), worst = Math.max(0, ...r.zs.map((z) => CX.abs(CX.sub(f(z), p)) / (1 + CX.abs(p))));
  check(`${name}: every z maps to p to 1e-9`, worst <= 1e-9, worst);
  // (the list itself, not its distinct points: a root listed twice is two dots on one spot)
  const distinct = r.zs.filter((z, i) => r.zs.findIndex((q) => CX.abs(CX.sub(q, z)) <= 1e-9 * (1 + CX.abs(z))) === i);
  check(`${name}: ${want} preimages, none twice`, r.zs.length === want && distinct.length === want, [r.zs.length, distinct.length]);
  check(`${name}: total ${want}`, r.total === want, r.total);
  check(`${name}: the multiplicities sum to the total`, !!r.mult && r.mult.length === r.zs.length && r.mult.reduce((a, m) => a + m, 0) === r.total, r.mult);
  return r;
}
const p = C(0.3, 0.7);
exact('z^8', [step('pown', { n: 8 })], p, 8);
exact('z^2 -> +1 -> z^2 (degree 4)', [step('pown', { n: 2 }), step('add', { c: '1' }), step('pown', { n: 2 })], p, 4);
exact('Möbius -> z^3', [step('mobius', { a: '1', b: '-i', c: '1', d: 'i' }), step('pown', { n: 3 })], p, 3);
exact('z^2 + 1 as a formula, then z^8 (degree 16)', [step('custom', { expr: 'z^2+1' }), step('pown', { n: 8 })], p, 16);
exact('z^8 -> z^8 (degree 64, the cap)', [step('pown', { n: 8 }), step('pown', { n: 8 })], p, 64);
// the planes in between: steps 2..3 only (a point of w3 seen in w1)
exact('z^2 -> +1 -> z^3, from w1 to w3', [step('pown', { n: 2 }), step('add', { c: '1' }), step('pown', { n: 3 })], p, 3, 1, 3);
// a critical value: z^2 at p = 0 has the double root 0 (once), at p = -0.01 the two roots ±0.1i
let r = exact('z^2 at p = -0.01', [step('pown', { n: 2 })], C(-0.01, 0), 2);
check('z^2 at p = -0.01: ±0.1i', r.exact && r.zs.some((z) => CX.abs(CX.sub(z, C(0, 0.1))) < 1e-12) && r.zs.some((z) => CX.abs(CX.sub(z, C(0, -0.1))) < 1e-12), JSON.stringify(r.zs));
// a critical value: the double root once, with its multiplicity, whichever op inverts it (IPOW, QUAD, JOUK), and
// through a later step (z^2 + z, then z^3, at -1/64: of the cube roots of -1/64 only -1/4 is critical, so 5 points, the
// double root -1/2 among them, good to about √ε there; the multiplicities sum to the total less the branches through
// infinity)
const critical = (name, steps, p, z0, m, n = 1) => {
  const ch = chain(steps), q = Inverse.pointPre(Inverse.planChain(ch.steps, ch.built), p);
  const at = q.exact ? q.zs.findIndex((z) => CX.abs(CX.sub(z, z0)) < 1e-7) : -1;
  check(`${name}: ${n} point${n > 1 ? 's' : ''}, ${JSON.stringify(z0)} ×${m} among them`, q.exact && q.zs.length === n && at >= 0 && !!q.mult && q.mult[at] === m && q.mult.reduce((a, k) => a + k, 0) <= q.total, JSON.stringify(q));
};
critical('z^2 at the critical value 0 (IPOW)', [step('pown', { n: 2 })], C(0, 0), C(0, 0), 2);
critical('z^8 at 0 (IPOW)', [step('pown', { n: 8 })], C(0, 0), C(0, 0), 8);
critical('z^2 + z at -1/4 (QUAD)', [step('custom', { expr: 'z^2+z' })], C(-0.25, 0), C(-0.5, 0), 2);
critical('Joukowski at 1', [step('joukowski')], C(1, 0), C(1, 0), 2);
critical('Joukowski at -1', [step('joukowski')], C(-1, 0), C(-1, 0), 2);
// RAT2: a simple root when the other has gone to infinity (w the value at infinity), the double root 0 listed once
{
  const ch = chain([step('custom', { expr: '\\frac{z^2+1}{z^2+z+1}' })]), plan = Inverse.planChain(ch.steps, ch.built);
  check('(z^2+1)/(z^2+z+1) is one RAT2 op', plan.ok && plan.ops.length === 1 && plan.ops[0].kind === 'RAT2', plan.ok ? plan.ops.map((o) => o.kind) : plan.reason);
}
critical('(z^2+1)/(z^2+z+1) at 1, its value at infinity (RAT2): the simple root 0', [step('custom', { expr: '\\frac{z^2+1}{z^2+z+1}' })], C(1, 0), C(0, 0), 1);
critical('z^2/(z^2+1) at 0 (RAT2): the double root 0', [step('custom', { expr: '\\frac{z^2}{z^2+1}' })], C(0, 0), C(0, 0), 2);
critical('z^2 + z, then z^3, at -1/64', [step('custom', { expr: 'z^2+z' }), step('pown', { n: 3 })], C(-1 / 64, 0), C(-0.5, 0), 2, 5);
// not exact: infinitely many branches, a degree the catalog does not invert, above the cap
for (const [name, steps] of [['exp', [step('exp')]], ['sin', [step('sin')]], ['z^3 + z (a cubic)', [step('custom', { expr: 'z^3+z' })]],
  ['z^8 -> z^16 (128 > the cap)', [step('pown', { n: 8 }), step('pown', { n: 16 })]]]) {
  const ch = chain(steps), q = Inverse.pointPre(Inverse.planChain(ch.steps, ch.built), p);
  check(`${name}: not exact (the app searches)`, !q.exact, JSON.stringify(q).slice(0, 120));
}
console.log(bad ? `${bad} of ${n} checks fail` : `all ${n} checks pass`);
process.exit(bad ? 1 : 0);

// Repeat × N (issue #6, part B): step.repeat = {n, len} on the last step of a block runs the block n times
// (Funcs.applyRepeats). Its values against a plain loop, its guarantees (degree d^n, a Möbius map stays one), its
// deformation copy by copy, the inverse renderer's ops (the block's ops n times), the TeX, d/dz after it (the circle
// formula), bypassed steps, and the refusals (a d/dz inside, too many steps).
// Run: node test/t_repeat.js   (exit code 1 on any failure)
global.CX = require('../src/cx.js');
global.Expr = require('../src/parse.js');
global.Funcs = require('../src/funcs.js');
global.Region = require('../src/region.js');
const Inverse = require('../src/inverse.js');
const C = CX.C;
let bad = 0, n = 0;
const check = (name, ok, info = '') => { n++; if (!ok) { bad++; console.log('FAIL', name, info); } };
const rel = (a, b) => CX.abs(CX.sub(a, b)) / Math.max(CX.abs(b), 1e-300);
const S = (type, params = {}, on = true) => ({ type, params: Object.assign(Funcs.defaults(type), params), on });
const Rp = (st, n, len) => Object.assign(st, { repeat: { n, len } });
const chain = (steps) => { const built = Funcs.applyRepeats(steps, steps.map((s) => Funcs.build(s))); return { steps, built, G: Funcs.stageFunctions(steps, built) }; };
const c = C(0.2, 0.1), sq = (u) => CX.add(CX.mul(u, u), c);

// ---- 1. values and stages
const A = chain([S('pown', { n: 2 }), Rp(S('add', { c: '0.2+0.1i' }), 3, 2)]);
for (const z of [C(0.3, 0.4), C(-0.5, 0.2), C(1.1, -0.7)]) check(`(z² + c)∘3 at ${z.re}${z.im >= 0 ? '+' : ''}${z.im}i`, rel(A.G[2](z), sq(sq(sq(z)))) < 1e-14);
check('the stage before the repeat\'s last step is the first pass (w₁ = z²)', rel(A.G[1](C(0.3, 0.4)), CX.mul(C(0.3, 0.4), C(0.3, 0.4))) < 1e-15);
check('n = 1 is the step itself', chain([S('pown', { n: 2 }), Rp(S('add', { c: '1' }), 1, 2)]).built[1].repeat === undefined);
const B = chain([S('sin'), S('pown', { n: 3 }, false), Rp(S('mul', { c: '0.7+0.2i' }), 3, 3)]);
const m = C(0.7, 0.2), zb = C(0.4, -0.3);
check('a bypassed step inside the block stays out of every pass', rel(B.G[3](zb), CX.mul(m, CX.sin(CX.mul(m, CX.sin(CX.mul(m, CX.sin(zb))))))) < 1e-14);
check('a bypassed last step: no repeat', chain([S('pown', { n: 2 }), Rp(S('add', { c: '1' }, false), 3, 2)]).built[1].repeat === undefined);

// ---- 2. guarantees
const pA = A.built[1].props;
check('z² + c three times ends in degree 4 at f₂ (f₂ then the block twice), F of degree 8', pA.polynomial && pA.deg === 4 && pA.degExact, JSON.stringify(pA));
const M = chain([Rp(S('mobius', { a: '1', b: '0.3', c: '-0.3', d: '1' }), 4, 1)]);
check('a Möbius map four times is a Möbius map, injective', M.built[0].props.mobius && M.built[0].props.injective && M.built[0].props.deg === 1);
check('exp twice is entire, not a polynomial', (() => { const p = chain([Rp(S('exp'), 2, 1)]).built[0].props; return p.entire && !p.polynomial; })());

// ---- 3. deformation copy by copy: 2 + 2·2 = 6 steps after f₂ … at t = 1/6 f₂ has run, at 1 the whole tail
const b2 = A.built[1], z0 = C(0.3, 0.4), w1 = A.G[1](z0);
check('the deformation runs 1 + 2·2 steps', b2.nat && b2.nat.n === 5, JSON.stringify(b2.nat));
check('H₀ is the identity, H₁ the tail', rel(b2.hom(0)(w1), w1) === 0 && rel(b2.hom(1)(w1), A.G[2](z0)) < 1e-15);
check('at t = 1/5: f₂ alone has run', rel(b2.hom(0.2)(w1), CX.add(w1, c)) < 1e-14);
check('at t = 2/5: then z² once more', rel(b2.hom(0.4)(w1), CX.mul(CX.add(w1, c), CX.add(w1, c))) < 1e-13);

// ---- 4. the inverse renderer, the TeX, d/dz
const pl = Inverse.planChain(M.steps, M.built);
check('a repeated Möbius map: the exact renderer inverts it (four Möbius ops)', pl.ok, pl.reason);
check('z² + c three times: the exact renderer\'s plan', Inverse.planChain(A.steps, A.built).ok);
const tx = A.built[1].tex({ s: 'w_1', p: 4 }).s;
check('TeX: (f₂ ∘ ⋯ ∘ f₁)^{∘2}(w₁ + c)', /^\\left\(f_\{2\}\\circ\\cdots\\circ f_\{1\}\\right\)\^\{\\circ 2\}/.test(tx) && tx.includes('w_1'), tx);
check('the repeat has no inverse step, and says why', A.built[1].inverse === null && /copy by copy/.test(A.built[1].inverseNote));
const D = chain([S('pown', { n: 2 }), Rp(S('add', { c: '0.2+0.1i' }), 2, 2), S('deriv')]);
const zd = C(0.3, 0.2), h = 1e-6, F2 = D.G[2];
const fd = CX.scale(CX.sub(F2(CX.add(zd, C(h, 0))), F2(CX.sub(zd, C(h, 0)))), 1 / (2 * h));
check('d/dz after a repeat (the circle formula) against a difference quotient', rel(D.G[3](zd), fd) < 1e-5, `${D.G[3](zd).re} ${fd.re}`);
check('no derivative formula for the repeat itself, in words', /numerically/.test(Funcs.derivAst(D.built[1]).error || ''));

// ---- 5. refusals
const E1 = chain([S('exp'), S('deriv'), Rp(S('sin'), 2, 3)]).built[2];
check('a d/dz inside the block is refused', !!E1.error && /d\/dz/.test(E1.error), JSON.stringify(E1.error));
const E2 = chain([S('exp'), S('sin'), S('cos'), S('tan'), S('sinh'), Rp(S('cosh'), 64, 6)]).built[5];
check('more than 256 steps in all is refused, naming the largest N', !!E2.error && /at most N = 42/.test(E2.error), JSON.stringify(E2.error));
const E3 = chain([Rp(S('zeta'), 20, 1)]).built[0];
check('a heavy step weighs more: ζ twenty times is refused, at most N = 16', !!E3.error && /at most N = 16/.test(E3.error), JSON.stringify(E3.error));
check('ζ sixteen times is drawn', !chain([Rp(S('zeta'), 16, 1)]).built[0].error);
check('repeatOk: a len past the chain\'s start is no repeat', Funcs.repeatOk([Rp(S('exp'), 2, 3)], 1) === null);

// ---- 6. N bound to a shared number (repeat.by): its value rounded, 1 … REPEAT_MAX; the stored n without it
Expr.setNames({ get: (nm) => ({ k: 2.6, big: 1000, neg: -3 })[nm], display: (nm) => nm });
const byN = (by) => Funcs.repeatOk([S('exp'), Rp(S('sin'), 2, 2)].map((st, i) => (i === 1 ? Object.assign(st, { repeat: { n: 2, len: 2, by } }) : st)), 2);
check('by k = 2.6: three passes', byN('k').n === 3);
check('by a large number: at most REPEAT_MAX', byN('big').n === Funcs.REPEAT_MAX);
check('by a negative number: one pass', byN('neg').n === 1);
check('by a number that is gone: the stored n', byN('gone').n === 2);
Expr.setNames(null);
console.log(bad ? `${bad} of ${n} checks fail` : `all ${n} checks pass`);
process.exit(bad ? 1 : 0);

// Sound (notes/sound/DESIGN.md): the pure parts. Calc.argStep and Calc.orderAt (the probe's exact arg steps and the
// order at a point, by the argument principle), winding counts, and the engine's scheduler and its guards (src/sound.js
// run in a sandbox against a mock AudioContext: off by default, consent, the queues, the cluster and storm guards, the
// suspended-context rule, the silent off, Esc). v15.2 (notes/sound/AS-BUILT-v152.md): palette B's parts (variation,
// repetition, clean edges), the scrub's landmarks, the phase harp (its low Ds count the winding number), curves sing
// (the loudest harmonic is 4 + W). Run: node test/t_sound.js
const vm = require('vm');
global.CX = require('../src/cx.js');
const Calc = require('../src/calc.js');
const C = CX.C, TAU = 2 * Math.PI;
