    const st = S.Harp(); S.harpStep(st, null, 0, 1 / 6 - 0.004, {});
    let k = 0; for (let i = 0; i < 50; i++) k += S.harpStep(st, null, i * 0.02, 1 / 6 + (i % 2 ? 0.008 : -0.008), { dt: 0.02 }).length;
    check('harp: a ±3° tremor across E plays nothing (hysteresis 3.75°)', k === 0, k);
    k = S.harpStep(st, null, 1, 1 / 6 + 0.012, { dt: 0.02 }).length;
    check('harp: past the hysteresis it plays once', k === 1, k);
    // the D-only zone (a trembling hand within 8 px of a zero): only the Ds sound, and the count stays exact
    const sh = S.Harp(); S.harpStep(sh, null, 0, 0.05, {});
    for (let i = 1; i <= 20; i++) { sh.notes = 0; S.harpStep(sh, null, i * 0.02, 0.05 + 0.1 * i, { dt: 0.02, shaky: true }); }
    check('harp: the D-only zone counts every D (2 turns: 2 up) and plays only those', sh.up === 2 && sh.down === 0, JSON.stringify(sh));
  }
  // v15.2 review fixes. math-1: whole turns hidden in one piece (|F| steady, a fast phase) are seen: e^{30z} moved up
  // by 0.40 and 0.42 turns arg F by 12.0 and 12.6 rad (they read −0.57 and 0.03, exact, before)
  {
    const e30 = (z) => expF(CX.scale(z, 30));
    for (const L of [0.4, 0.42, 25.1 / 30]) {
      const r = Calc.argStep(e30, C(0, 0), null, C(0, L), null);
      check(`math-1: argStep e^{30z} over ${L}i is ${(30 * L).toFixed(2)} rad`, r.exact && Math.abs(r.d - 30 * L) < 1e-9, JSON.stringify(r));
    }
    const r = Calc.argStep((z) => CX.sin(CX.scale(z, 20)), C(-0.3, 1), null, C(0.3, 1), null);
    check('math-1: argStep sin(20z) along Im z = 1, 0.6 wide: −12 rad', r.exact && Math.abs(r.d + 12) < 1e-6, JSON.stringify(r));
    // a pointer loop round nothing for e^{30z} (0.42 up in one event, 42 slow steps back): 0 Ds (was −2)
    const S = makeEnv().Sound, st = S.Harp();
    let z0 = C(0, 0), g0 = e30(z0), phi = 0;
    S.harpStep(st, null, 0, phi, {});
    const path = [C(0, 0.42)]; for (let i = 41; i >= 0; i--) path.push(C(0, 0.01 * i));
    for (const z1 of path) { const g1 = e30(z1), q = Calc.argStep(e30, z0, g0, z1, g1); phi += q.d / TAU; z0 = z1; g0 = g1; S.harpStep(st, null, 0, phi, { dt: 0.016 }); }
    check('math-1: a pointer loop round nothing for e^{30z}: 0 low Ds net', st.up === st.down && Math.abs(phi) < 1e-9, JSON.stringify({ up: st.up, down: st.down, phi }));
  }
  // sound-2: the singer has a note for W = −3 … 20 only (harmonic 4 + W of D3); outside, the callers ping or speak
  {
    const S = makeEnv().Sound;
    check('sound-2: singable W −3 … 20, not −4, −5 or 21', [-3, 0, 1, 20].every((W) => S.singable(W)) && ![-4, -5, 21, 0.5].some((W) => S.singable(W)));
    const ph = new Float64Array(256); for (let j = 0; j < 256; j++) ph[j] = -4 * j / 256;
    const a = S.curveAmps(ph, -4);
    check('sound-2: W = −4 has no harmonic (why it is not sung)', a.n0 === 0 && a.A.every((x) => x < 0.05), JSON.stringify(a.A.slice(0, 4)));
  }
  // sound-3: a finger held still 10 px from a zero (F = z, 1 px a unit), on a line, with a 9 Hz tremor of ±1.5 px: the
  // band of 2.5 px (the app's |F'/F| · 2.5 px) plucks nothing; with the fixed 7.5° band it chattered
  {
    const S = makeEnv().Sound;
    const held = (band) => {
      const st = S.Harp(); let phi = null, prev = null;
      for (let k = 0; k < 600; k++) {
        const t = k / 60, x = 10 + 1.5 * Math.sin(TAU * 9 * t), y = 1.5 * Math.sin(TAU * 8.3 * t + 1);
        const a = Math.atan2(y, x) / TAU; if (phi === null) phi = a; else { let d = a - prev; d -= Math.round(d); phi += d; } prev = a;
        S.harpStep(st, null, t, phi, { dt: 1 / 60, h: band ? (1 / Math.hypot(x, y)) * 2.5 / TAU : 0 });
      }
      return st.notes;
    };
    const n0 = held(false), n1 = held(true);
    check('sound-3: a held finger near a zero: 0 notes with the 2.5 px band (many without)', n1 === 0 && n0 > 10, JSON.stringify({ fixed: n0, band: n1 }));
    // the band never loses a count: a loop round the zero at 10 px from arg 0.4 turn, 3 laps: 3 Ds up
    const st = S.Harp(); let phi = 0.4; S.harpStep(st, null, 0, phi, {});
    for (let i = 1; i <= 360; i++) { phi = 0.4 + 3 * i / 360; S.harpStep(st, null, i / 60, phi, { dt: 1 / 60, h: 0.1 * 2.5 / TAU }); }
    check('sound-3: with the band, 3 laps round a zero still give 3 low Ds', st.up === 3 && st.down === 0, JSON.stringify(st));
  }
  // curves sing: the phase along a closed curve played as one period; its loudest harmonic is 4 + W (D5 for 0, F♯5 for
  // 1, A5 for 2, A4 for −1), and the spectral centre is exactly W
  {
    const S = makeEnv().Sound;
    const sample = (F, c, r, M = 512) => { const ph = new Float64Array(M); let z0 = C(c.re + r, c.im), g0 = F(z0), acc = Math.atan2(g0.im, g0.re) / TAU; ph[0] = acc; for (let j = 1; j <= M; j++) { const th = TAU * j / M, z1 = C(c.re + r * Math.cos(th), c.im + r * Math.sin(th)), g1 = F(z1); acc += Calc.argStep(F, z0, g0, z1, g1).d / TAU; if (j < M) ph[j] = acc; z0 = z1; g0 = g1; } return { ph, W: Math.round(acc - ph[0]) }; };
    const loudest = (A) => A.indexOf(Math.max(...A)) + 1;
    const centre = (A, W) => { let e = 0, m = 0; for (let n = 1; n <= A.length; n++) { e += A[n - 1] * A[n - 1]; m += (n - 4) * A[n - 1] * A[n - 1]; } return m / e; };
    const cases = [['z − 0.6 on |z| = 1', (z) => sub(z, C(0.6, 0)), C(0, 0), 1, 1], ['z³ − 1 on |z| = 1.5', (z) => sub(mul(z, mul(z, z)), C(1, 0)), C(0, 0), 1.5, 3],
      ['(z − ½)/(z + ½) on |z| = 1', (z) => CX.div(sub(z, C(0.5, 0)), CX.add(z, C(0.5, 0))), C(0, 0), 1, 0], ['1/z on |z| = 1', (z) => CX.inv(z), C(0, 0), 1, -1],
      ['z² with the zero off centre', (z) => mul(sub(z, C(0.5, 0.2)), sub(z, C(0.5, 0.2))), C(0, 0), 1, 2], ['e^z on |z| = 3 (W = 0, wide)', expF, C(0, 0), 3, 0]];
    for (const [what, F, c, r, W] of cases) {
      const sm = sample(F, c, r), a = S.curveAmps(sm.ph, sm.W);
      check(`curves sing: ${what}: W = ${W}, the loudest harmonic ${4 + W}`, sm.W === W && a.n0 === 4 + W && loudest(a.A) === 4 + W, JSON.stringify({ W: sm.W, loud: loudest(a.A), A: a.A.slice(0, 9).map((x) => +x.toFixed(3)) }));
      if (W !== 0 || what.startsWith('(')) check(`curves sing: ${what}: the spectral centre is W (±0.05)`, Math.abs(centre(a.A, W) - W) < 0.05, centre(a.A, W));
    }
  }
  // no Web Audio: everything is a no-op
  {
    const e = makeEnv({ noAudio: true });
    e.Sound.set({ on: true });
    check('no Web Audio: no error, nothing plays', e.Sound.state().supported === false && e.Sound.play('toggleOn', {}) === false);
  }
  await flush();
  console.log(`${n - bad}/${n} sound checks passed`);
  if (bad) process.exitCode = 1;
})();

// v16.5 rail (notes/ux-build/rail/SPEC.md 5.1): refKey, samePick's keys, gridStep, railPull, the turn-exact glide and
// its detents, the perpendicular circle through two gliders on one circle (orthogonal, through both; antipodes: the
// diameter), circle3 and touch with picks on C. Run: node test/t_ux165_rail.js
'use strict';
const path = require('path');
global.self = global;
const C = require(path.join(__dirname, '..', 'src', 'constr.js'));
let pass = 0, fail = 0;
const ok = (c, m) => { if (c) pass++; else { fail++; console.log('FAIL', m); } };
const near = (a, b, e = 1e-12) => Math.abs(a - b) <= e;

// ---- refKey
const m1 = { meet: [{ s: 'a', part: 0 }, { s: 'b', part: 0 }], index: 0 };
const m2 = { meet: [{ s: 'a', part: 0 }, { s: 'b', part: 0 }], index: 1 };
const m1b = { meet: [{ s: 'b', part: 0 }, { s: 'a', part: 0 }], index: 0 };
ok(C.refKey(m1) !== C.refKey(m2), 'two crossings of one pair differ');
ok(C.refKey(m1) === C.refKey(m1b), 'the same crossing, either order, is one key');
ok(!/undefined/.test(C.refKey(m1)), 'a meet key is never s:undefined: ' + C.refKey(m1));
ok(C.refKey({ meet: [{ s: 'a', part: 0 }, { s: 'c', part: 1 }], seed: [0.1, 0.2] }) !== C.refKey({ meet: [{ s: 'a', part: 0 }, { s: 'c', part: 1 }], seed: [0.3, 0.2] }), 'seeded crossings differ by seed');
ok(C.refKey({ pend: 0 }) === 'pend:0' && C.refKey({ pend: 1 }) === 'pend:1', 'pending pick keys');
ok(C.refKey({ meet: [{ disp: 'unit' }, { s: 'a', part: 0 }], index: 0 }) === 'm:c:a:0|d:unit:0', 'a crossing with a display curve');
ok(C.refKey({ s: 'z0' }) === C.refKey({ s: 'z0' }), 'an existing point twice is one key');

// ---- gridStep: one of the drawn tiers, >= 14 px
for (const [s, want] of [[52, 0.5], [520, 0.05], [5.2, 5], [14, 1], [28, 0.5], [100, 0.5], [1000, 0.05], [2.6, 10]]) ok(C.gridStep(s) === want, `gridStep(${s}) = ${C.gridStep(s)}, want ${want}`);
for (let s = 0.5; s < 20000; s *= 1.37) {
  const st = C.gridStep(s), d0 = Math.pow(10, Math.ceil(Math.log10(8 / s)));
  ok(st * s >= 14 - 1e-9, `gridStep(${s}) at least 14 px`);
  ok(C.GRID_TIERS.some((m) => near(st, +(d0 * m).toPrecision(12), 1e-15 * st)), `gridStep(${s}) is a drawn tier`);
}

// ---- railPull
const P = C.railPull, R = C.RAIL;
ok(P(null, 15.9, 0, false).zone === 'glide' && P(null, 16, 0, false).zone === 'stretch', 'mouse glide/stretch at 16');
ok(P(null, 23.9, 0, true).zone === 'glide' && P(null, 24, 0, true).zone === 'stretch', 'touch glide/stretch at 24');
ok(P(null, 79.9, 0, false).zone === 'stretch' && P(null, 80, 0, false).zone === 'free', 'mouse yank at 80');
ok(P(null, 127, 0, true).zone === 'stretch' && P(null, 128, 0, true).zone === 'free', 'touch yank at 128');
{
  // 40 px for 100 ms, then back: no let-go
  let st = null, z;
  for (let t = 0; t <= 100; t += 16) { z = P(st, 40, t, false); st = z.state; ok(z.zone === 'stretch', '40 px held ' + t + ' ms still stretch'); }
  z = P(st, 30, 116, false); st = z.state; ok(z.zone === 'stretch' && st === null, 'back under 40: the dwell resets');
  z = P(st, 40, 140, false); st = z.state; ok(z.zone === 'stretch', 'a new run starts its own dwell');
  // 40 px for 130 ms: let go
  st = null; let freed = -1;
  for (let t = 0; t <= 130; t += 10) { z = P(st, 41, t, false); st = z.state; if (z.zone === 'free' && freed < 0) freed = t; }
  ok(freed === 120, '40 px held 130 ms frees (at ' + freed + ' ms)');
  // touch: 64 for 120 ms
  st = null; for (let t = 0; t < 120; t += 16) { z = P(st, 64, t, true); st = z.state; ok(z.zone === 'stretch', 'touch 64 px before the dwell'); }
  z = P(st, 64, 121, true); ok(z.zone === 'free', 'touch 64 px held 121 ms frees');
  ok(R.dwell === 120 && R.mouse.free === 40 && R.touch.free === 64, 'the RAIL table');
}

// ---- the turn-exact glide on a plain circle
const unit = { id: 'u', kind: 'circle', c: [0, 0], r: 1, ci: 0, visible: true };
const pu = C.pieces(unit, {})[0];
const eq2 = (a, b) => a[0] === b[0] && a[1] === b[1] && Object.is(a[0] + 0, b[0] + 0);
ok(eq2(C.glide(pu, 0.25), [0, 1]), 'unit circle t = 1/4 is i bitwise: ' + C.glide(pu, 0.25));
ok(eq2(C.glide(pu, 0.5), [-1, 0]) && eq2(C.glide(pu, 0.75), [0, -1]) && eq2(C.glide(pu, 0), [1, 0]) && eq2(C.glide(pu, 1), [1, 0]), 'the quarter turns exact');
for (let k = 0; k < 24; k++) {
  const a = C.glide(pu, k / 24);
  ok(near(Math.hypot(a[0], a[1]), 1, 3e-16), 'on the circle');
  ok(near(a[0], Math.cos(2 * Math.PI * k / 24), 2e-15) && near(a[1], Math.sin(2 * Math.PI * k / 24), 2e-15), 'within a few ulp of cos/sin');
}
// t and t + 1/2 whose difference is exact (dyadic t): bitwise antipodes
for (const t of [0.125, 0.0625, 0.3125, 0.1875, 0.375]) { const a = C.glide(pu, t), b = C.glide(pu, t + 0.5); ok(a[0] === -b[0] && a[1] === -b[1], 'bitwise antipodes at ' + t); }
// projectPiece: 89 degrees -> about 1/4 (the detent itself is the interface's; here the parameter and the glide agree)
{
  const pr = C.projectPiece(pu, [Math.cos(89 * Math.PI / 180) * 1.01, Math.sin(89 * Math.PI / 180) * 1.01]);
  ok(near(pr.t, 89 / 360, 1e-12), 'projection 89 deg -> t = 89/360');
}

// ---- the perpendicular circle through two gliders on one circle
function scene(circ, ts, extra) {
  const st = { shapes: [Object.assign({ id: 'u', ci: 0, visible: true }, circ),
    ...ts.map((t, i) => ({ id: 'g' + i, kind: 'point', p: [0, 0], t, def: { op: 'glider', args: [{ s: 'u', part: 0 }] } })),
    ...(extra || [])], targets: [], steps: [] };
  C.recompute(st, { all: true }, {});
  return st;
}
const perpK = (circ, ta, tb, flip) => {
  const st = scene(circ, [ta, tb], [{ id: 'K', kind: 'circle', c: [0, 0], r: 1, def: Object.assign({ op: 'perp', args: [{ s: 'u', part: 0 }, { s: 'g0' }, { s: 'g1' }], fill: 'none', nk: 'circle' }, flip != null ? { flip } : {}) }]);
  return { st, K: st.shapes.find((s) => s.id === 'K'), P: st.shapes[1].p, Q: st.shapes[2].p };
};
let seed = 12345;
const rnd = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
for (const circ of [{ kind: 'circle', c: [0, 0], r: 1 }, { kind: 'circle', c: [0.3, 0.2], r: 1.5 }]) {
  for (let i = 0; i < 20; i++) {
    const ta = rnd(), tb = ta + 0.05 + 0.4 * rnd();
    const { K, P, Q } = perpK(circ, ta, tb);
    ok(!K.cundef && (K.kind === 'circle' || K.kind === 'line'), 'K defined ' + JSON.stringify(K.cundef));
    if (K.kind === 'circle') {
      const dc = Math.hypot(K.c[0] - circ.c[0], K.c[1] - circ.c[1]);
      const cos = (dc * dc - K.r * K.r - circ.r * circ.r) / (2 * K.r * circ.r);
      ok(Math.abs(cos) <= 1e-12 * Math.max(1, dc * dc / (K.r * circ.r)), `orthogonal |cos| = ${cos}`);
      ok(near(Math.hypot(P[0] - K.c[0], P[1] - K.c[1]), K.r, 1e-12 * Math.max(1, K.r)) && near(Math.hypot(Q[0] - K.c[0], Q[1] - K.c[1]), K.r, 1e-12 * Math.max(1, K.r)), 'through P and Q');
    }
  }
  for (const k of [0, 1, 5, 7, 11, 13, 20]) {
    const { K, P } = perpK(circ, k / 24, (k + 12) / 24);
    ok(K.kind === 'line' && K._g && K._g.A === 0, `k/24 and (k+12)/24 -> a line (A = 0) on c = ${circ.c} (k = ${k}): ${K.kind} A=${K._g && K._g.A}`);
    if (K._g) {
      const f = (z) => 2 * (K._g.B[0] * (z[0] - K._g.o[0]) + K._g.B[1] * (z[1] - K._g.o[1])) + K._g.C;
      ok(Math.abs(f(circ.c)) <= 1e-12 && Math.abs(f(P)) <= 1e-12 * circ.r * 4, 'the line through the centre and P');
    }
  }
  // 1e-6 of a turn off the antipode: a circle (the rule is on the parameters, not a tolerance on geometry)
  const { K: K2 } = perpK(circ, 0.1, 0.6 + 1e-6);
  ok(K2.kind === 'circle' && K2.r > 1e4, 'a pair 1e-6 turn off antipodal is a (huge) circle: ' + K2.kind + ' r=' + K2.r);
}
// the line keeps its side across the switch: the half-plane to the left of P -> Q, as the circle it is the limit of
{
  // (a K made before, its flip fixed: a glider dragged onto the antipode turns the near circle into the line, same normal)
  for (const k of [1, 13, 7]) for (const fl of [false, true]) {
    const a = perpK({ kind: 'circle', c: [0.3, 0.2], r: 1.5 }, k / 24, (k + 12) / 24, fl).K, b = perpK({ kind: 'circle', c: [0.3, 0.2], r: 1.5 }, k / 24, (k + 12) / 24 - 1e-9, fl).K, c = perpK({ kind: 'circle', c: [0.3, 0.2], r: 1.5 }, k / 24, (k + 12) / 24 + 1e-9, fl).K;
    const n = a._g.B, nb = b._g.B, nc = c._g.B;
    ok(a._g.A === 0 && n[0] * nb[0] + n[1] * nb[1] > 0.999 && n[0] * nc[0] + n[1] * nc[1] > 0.999, 'the diameter continues the near-antipodal circles (k = ' + k + ', flip ' + fl + ')');
  }
}
// ---- circle3 of three gliders on one circle: that circle; touch with T and P on C: C (the model)
{
  const st = scene({ kind: 'circle', c: [0, 0], r: 1 }, [0.1, 0.35, 0.8], [{ id: 'K3', kind: 'circle', c: [0, 0], r: 1, def: { op: 'circle3', args: [{ s: 'g0' }, { s: 'g1' }, { s: 'g2' }], fill: 'none' } }]);
  const K3 = st.shapes.find((s) => s.id === 'K3');
  ok(!K3.cundef && near(K3.r, 1, 1e-14) && near(K3.c[0], 0, 1e-14) && near(K3.c[1], 0, 1e-14), 'circle3 of three gliders on the unit circle is the unit circle: ' + K3.c + ' ' + K3.r);
  const st2 = scene({ kind: 'circle', c: [0, 0], r: 1 }, [0.1, 0.35], [{ id: 'T', kind: 'circle', c: [0, 0], r: 1, def: { op: 'touch', args: [{ s: 'u', part: 0 }, { s: 'g0' }, { s: 'g1' }], fill: 'none', nk: 'circle' } }]);
  const T = st2.shapes.find((s) => s.id === 'T');
  ok(!T.cundef && near(T.r, 1, 1e-12), 'touch with T and P on C is C itself');
}
console.log(`t_ux165_rail: ${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

// The zeros-and-poles step (funcs.js 'zp', 2026-10-22): f(z) = a prod(z - zeta_k) / prod(z - p_j).
// (a) the lists parse (empty, brackets, spaces) and an item written back parses to exactly the same value;
// (b) f is a prod / prod (= the expanded P/Q), infinite at a pole, finite where products alone would overflow;
// (c) guarantees: rational of exact degree max(#zeros, #poles), polynomial iff no pole, Moebius iff degree 1, proper
//     iff more zeros than poles, constant cases (a = 0, nothing, a cancelled pair), the natural domain, inverses;
// (d) the factored TeX parses back to the same map;
// (e) the natural path: H_0 = id, H_1 = f, continuous at the first frames, analytic for each t, never degenerate;
//     the zoom path about zeta_1 exactly (the listed order: no jump while another zero is dragged), with poles
//     the rational zoom path about a zero; the caption names the zeros as the card does;
// (f) the inverse renderer: degree <= 2 exact (MOB, AFF, QUAD, RAT2) with preimages that map back, degree >= 3
//     forward with the reason; the limit at infinity (sphere.js);
// (g) d/dz of the step (Funcs.derivAst) against a numeric derivative; the step's own 'derivative' action;
// (h) conversions: polynomial, rational, custom rational -> zeros and poles -> coefficients, the same map;
// (i) GLChain: the product-form shader's signature counts only the numbers of zeros and poles (a drag never
//     recompiles), and adding one changes it.
// Run: node test/t_zp.js
global.CX = require('../src/cx.js');
global.Expr = require('../src/parse.js');
global.Funcs = require('../src/funcs.js');
global.Region = require('../src/region.js');
const Inverse = require('../src/inverse.js');
const GLChain = require('../src/glsl.js');
const F = global.Funcs;
const { C } = CX;
let checks = 0, failed = 0;
const check = (name, cond, got) => { checks++; if (!cond) { failed++; console.log('FAIL', name, got === undefined ? '' : JSON.stringify(got)); } };
let seed = 11;
const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
const rc = (r = 2) => C(+(rnd() * 2 * r - r).toFixed(3), +(rnd() * 2 * r - r).toFixed(3));
const pts = Array.from({ length: 60 }, () => C(rnd() * 5 - 2.5, rnd() * 5 - 2.5));
const ZP = (params) => F.build({ type: 'zp', params: Object.assign(F.defaults('zp'), params) });
const rel = (a, b) => CX.abs(CX.sub(a, b)) / (1 + CX.abs(b));
const list = (vs) => vs.map(F.zpItem).join(', ');

// (a) lists
